1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"math/big"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14		"unicode"
15		"unicode/utf16"
16		"unicode/utf8"
17	)
18	
19	// Point 是一条序列上某个时间戳的采样值。
20	type Point struct {
21		Timestamp int64   `json:"timestamp"`
22		Value     float64 `json:"value"`
23	}
24	
25	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
26	type SeriesView struct {
27		Name   string            `json:"name"`
28		Labels map[string]string `json:"labels"`
29		Points []Point           `json:"points"`
30	}
31	
32	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
33	type QuerySeries struct {
34		Name    string            `json:"name"`
35		Labels  map[string]string `json:"labels"`
36		Count   int               `json:"count"`
37		Average float64           `json:"average"`
38	}
39	
40	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
41	type QueryResult struct {
42		Status string        `json:"status"`
43		Op     string        `json:"op"`
44		Series []QuerySeries `json:"series"`
45	}
46	
47	// BatchResult 是一批采样点写入成功后的结果。
48	type BatchResult struct {
49		Status     string       `json:"status"`
50		Added      int          `json:"added"`
51		Duplicates int          `json:"duplicates"`
52		Series     []SeriesView `json:"series"`
53	}
54	
55	// SeriesRef 标识一条序列：指标名加完整标签集合。
56	// 缺少某个标签与该标签值为空字符串属于不同序列。
57	type SeriesRef struct {
58		Name   string            `json:"name"`
59		Labels map[string]string `json:"labels"`
60	}
61	
62	// Conflict 描述同一序列同一时间戳已存在不同的值。
63	type Conflict struct {
64		Series    SeriesRef `json:"series"`
65		Timestamp int64     `json:"timestamp"`
66		Existing  float64   `json:"existing"`
67		Submitted float64   `json:"submitted"`
68	}
69	
70	// LineError 是一行（一批）输入失败后的结构化结果。
71	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
72	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
73	type LineError struct {
74		Status   string    `json:"status"`
75		Line     int       `json:"line,omitempty"`
76		Index    int       `json:"index,omitempty"`
77		Error    string    `json:"error"`
78		Conflict *Conflict `json:"conflict,omitempty"`
79	}
80	
81	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
82	type MetricStore struct {
83		series map[seriesID]*storedSeries
84	}
85	
86	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
87	type seriesID struct {
88		name string
89		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
90		sig string
91	}
92	
93	type storedSeries struct {
94		ref    SeriesRef
95		points map[int64]float64
96	}
97	
98	// NewMetricStore 创建一个空的指标存储。
99	func NewMetricStore() *MetricStore {
100		return &MetricStore{series: make(map[seriesID]*storedSeries)}
101	}
102	
103	// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
104	// 调用方对副本的增删改不影响存储中的序列身份。
105	func cloneLabels(labels map[string]string) map[string]string {
106		out := make(map[string]string, len(labels))
107		for k, v := range labels {
108			out[k] = v
109		}
110		return out
111	}
112	
113	func sortedKeys(m map[string]string) []string {
114		keys := make([]string, 0, len(m))
115		for k := range m {
116			keys = append(keys, k)
117		}
118		sort.Strings(keys)
119		return keys
120	}
121	
122	func makeSeriesID(name string, labels map[string]string) seriesID {
123		var b strings.Builder
124		for _, k := range sortedKeys(labels) {
125			v := labels[k]
126			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
127		}
128		return seriesID{name: name, sig: b.String()}
129	}
130	
131	// labelPair 是标签键值对字典序比较的单元。
132	type labelPair struct {
133		Key, Value string
134	}
135	
136	func sortedPairs(labels map[string]string) []labelPair {
137		keys := sortedKeys(labels)
138		pairs := make([]labelPair, len(keys))
139		for i, k := range keys {
140			pairs[i] = labelPair{Key: k, Value: labels[k]}
141		}
142		return pairs
143	}
144	
145	func compareLabelPairs(a, b []labelPair) int {
146		n := len(a)
147		if len(b) < n {
148			n = len(b)
149		}
150		for i := 0; i < n; i++ {
151			if a[i].Key != b[i].Key {
152				return strings.Compare(a[i].Key, b[i].Key)
153			}
154			if a[i].Value != b[i].Value {
155				return strings.Compare(a[i].Value, b[i].Value)
156			}
157		}
158		switch {
159		case len(a) < len(b):
160			return -1
161		case len(a) > len(b):
162			return 1
163		}
164		return 0
165	}
166	
167	var (
168		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
169		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
170	)
171	
172	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
173	// 成功时返回非 nil 的 *BatchResult 或 *QueryResult 且错误为 nil；任何失败都返回
174	// 真正的 nil 结果与 *LineError，调用方直接比较 result == nil 即可判定失败，
175	// 无须先区分结果类型。空写入数组与无命中的查询仍是成功，结果不为 nil。
176	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
177		top, ok, lerr := decodeTopValue(line)
178		if lerr != nil {
179			return nil, lerr
180		}
181		switch ok {
182		case '[':
183			var items []json.RawMessage
184			if err := json.Unmarshal(top, &items); err != nil {
185				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
186			}
187			// 不能把 *BatchResult 直接装进 any 返回：失败时它是带类型的 nil 指针，
188			// 接口值非 nil，调用方会把失败误判为有结果。
189			batch, lerr := s.ingestItems(items)
190			if lerr != nil {
191				return nil, lerr
192			}
193			return batch, nil
194		case '{':
195			// 同上：失败时不能把带类型 nil 的 *QueryResult 装进 any。
196			query, lerr := s.queryFromObject(top)
197			if lerr != nil {
198				return nil, lerr
199			}
200			return query, nil
201		default:
202			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
203		}
204	}
205	
206	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
207	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
208	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
209		top, ok, lerr := decodeTopValue(line)
210		if lerr != nil {
211			return nil, lerr
212		}
213		if ok != '[' {
214			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
215		}
216		var items []json.RawMessage
217		if err := json.Unmarshal(top, &items); err != nil {
218			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
219		}
220		return s.ingestItems(items)
221	}
222	
223	// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
224	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
225		top, ok, lerr := decodeTopValue(line)
226		if lerr != nil {
227			return nil, lerr
228		}
229		if ok != '{' {
230			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
231		}
232		return s.queryFromObject(top)
233	}
234	
235	// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
236	// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
237	// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
238	// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
239	//
240	// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
241	// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
242	func validateLineText(line string) *LineError {
243		if !utf8.ValidString(line) {
244			return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
245		}
246		inString := false
247		for i := 0; i < len(line); i++ {
248			c := line[i]
249			if !inString {
250				if c == '"' {
251					inString = true
252				}
253				continue
254			}
255			switch c {
256			case '"':
257				inString = false
258			case '\\':
259				if i+1 >= len(line) {
260					break // 悬空反斜杠：交给 JSON 解析器报错
261				}
262				if line[i+1] != 'u' {
263					i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
264					continue
265				}
266				// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
267				r, size := decodeJSONHexEscape(line, i+1)
268				if size == 0 {
269					return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
270				}
271				if !utf16.IsSurrogate(r) {
272					i += 5
273					continue
274				}
275				if r >= 0xDC00 {
276					// 单独出现的低代理项。
277					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
278				}
279				// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
280				loPos := i + 6 // 第一个转义之后的字符位置
281				if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
282					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
283				}
284				lo, loSize := decodeJSONHexEscape(line, loPos+1)
285				if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
286					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
287				}
288				i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
289			}
290		}
291		return nil
292	}
293	
294	// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
295	// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
296	func decodeJSONHexEscape(line string, pos int) (rune, int) {
297		if pos+4 >= len(line) {
298			return 0, 0
299		}
300		var v rune
301		for j := pos + 1; j <= pos+4; j++ {
302			c := line[j]
303			var d rune
304			switch {
305			case c >= '0' && c <= '9':
306				d = rune(c - '0')
307			case c >= 'a' && c <= 'f':
308				d = rune(c-'a') + 10
309			case c >= 'A' && c <= 'F':
310				d = rune(c-'A') + 10
311			default:
312				return 0, 0
313			}
314			v = v<<4 | d
315		}
316		return v, 5
317	}
318	
319	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
320	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
321	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
322		if lerr := validateLineText(line); lerr != nil {
323			return nil, 0, lerr
324		}
325		dec := json.NewDecoder(strings.NewReader(line))
326		var top json.RawMessage
327		if err := dec.Decode(&top); err != nil {
328			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
329		}
330		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
331		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
332			if err == nil {
333				err = fmt.Errorf("unexpected content after the JSON value")
334			}
335			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
336		}
337		trimmed := strings.TrimSpace(string(top))
338		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
339			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
340		}
341		return top, trimmed[0], nil
342	}
343	
344	// fieldReader 从 dec 读取并校验当前字段的值，写入调用方持有的结果。
345	// 采样点与查询对象各自注册自己允许的字段及字段含义。
346	type fieldReader func(dec *json.Decoder) error
347	
348	// parseStrictObject 是写入采样点与查询对象共用的严格对象校验骨架：
349	// 仅允许 fields 中列出的字段（未知字段先于判重被拒绝），同一对象内按转义还原
350	// 后的字段名判重（即使两个值相同也拒绝；判重不跨对象、不跨层级），按输入次序
351	// 逐字段调用对应的 fieldReader，对象结束后要求输入恰好耗尽，最后按 required
352	// 的顺序报告缺失的必填字段。notObjectMsg 与 trailingMsg 由调用方给出，
353	// 保留各自输入的措辞。
354	func parseStrictObject(raw json.RawMessage, notObjectMsg, trailingMsg string, required []string, fields map[string]fieldReader) error {
355		dec := json.NewDecoder(bytes.NewReader(raw))
356		dec.UseNumber()
357	
358		tok, err := dec.Token()
359		if err != nil {
360			return err
361		}
362		if d, ok := tok.(json.Delim); !ok || d != '{' {
363			return fmt.Errorf("%s", notObjectMsg)
364		}
365	
366		present := make(map[string]bool)
367		for dec.More() {
368			keyTok, err := dec.Token()
369			if err != nil {
370				return err
371			}
372			key := keyTok.(string)
373			read, ok := fields[key]
374			if !ok {
375				return fmt.Errorf("unknown field %q", key)
376			}
377			if present[key] {
378				return fmt.Errorf("duplicate field %q", key)
379			}
380			present[key] = true
381			if err := read(dec); err != nil {
382				return err
383			}
384		}
385		if _, err := dec.Token(); err != nil { // 消耗 '}'
386			return err
387		}
388		if _, err := dec.Token(); err != io.EOF {
389			if err == nil {
390				return fmt.Errorf("%s", trailingMsg)
391			}
392			return err
393		}
394	
395		for _, field := range required {
396			if !present[field] {
397				return fmt.Errorf("missing required field %q", field)
398			}
399		}
400		return nil
401	}
402	
403	// readNameField 读取写入与查询共用的指标名字段：必须是非空字符串。
404	func readNameField(dec *json.Decoder, dst *string) error {
405		t, err := dec.Token()
406		if err != nil {
407			return err
408		}
409		s, ok := t.(string)
410		if !ok {
411			return fmt.Errorf(`field "name" must be a string`)
412		}
413		if s == "" {
414			return fmt.Errorf(`field "name" must be a non-empty string`)
415		}
416		*dst = s
417		return nil
418	}
419	
420	// readInt64Field 读取 int64 毫秒整数字段（timestamp/start/end）：
421	// 必须是 JSON 整数且在 int64 范围内，数字字符串、布尔值、带小数点一律拒绝。
422	func readInt64Field(dec *json.Decoder, field string, dst *int64) error {
423		n, err := nextJSONNumber(dec, field)
424		if err != nil {
425			return err
426		}
427		v, err := parseJSONInt(n)
428		if err != nil {
429			return fmt.Errorf("field %q: %s", field, err)
430		}
431		*dst = v
432		return nil
433	}
434	
435	// readFiniteFloatField 读取采样值字段：必须是可表示为有限 float64 的 JSON 数字。
436	func readFiniteFloatField(dec *json.Decoder, field string, dst *float64) error {
437		n, err := nextJSONNumber(dec, field)
438		if err != nil {
439			return err
440		}
441		v, err := parseFiniteFloat(n)
442		if err != nil {
443			return fmt.Errorf("field %q: %s", field, err)
444		}
445		*dst = v
446		return nil
447	}
448	
449	// readLabelsField 读取标签对象字段并写入 dst；notObjectMsg 保留各输入侧措辞。
450	func readLabelsField(dec *json.Decoder, notObjectMsg string, dst *map[string]string) error {
451		labels, err := parseLabels(dec, notObjectMsg)
452		if err != nil {
453			return err
454		}
455		*dst = labels
456		return nil
457	}
458	
459	type parsedSample struct {
460		name   string
461		ts     int64
462		value  float64
463		labels map[string]string
464	}
465	
466	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
467	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
468	func parseSample(raw json.RawMessage) (parsedSample, error) {
469		var p parsedSample
470		p.labels = map[string]string{}
471		err := parseStrictObject(raw,
472			"each sample must be a JSON object",
473			"unexpected content after the sample object",
474			[]string{"name", "timestamp", "value"},
475			map[string]fieldReader{
476				"name":      func(dec *json.Decoder) error { return readNameField(dec, &p.name) },
477				"timestamp": func(dec *json.Decoder) error { return readInt64Field(dec, "timestamp", &p.ts) },
478				"value":     func(dec *json.Decoder) error { return readFiniteFloatField(dec, "value", &p.value) },
479				"labels": func(dec *json.Decoder) error {
480					return readLabelsField(dec, `field "labels" must be an object of string keys to string values`, &p.labels)
481				},
482			})
483		return p, err
484	}
485	
486	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
487	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
488	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
489	// 判重先于值的类型校验：某个键第一次出现时若值不是字符串，仍报告该值的类型
490	// 错误；而该键再次出现时，无论第二次的值是什么（数字、布尔、null、对象、数组），
491	// 都先报告重复标签键，不能让第二次值的类型掩盖键重复。
492	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
493	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
494		t, err := dec.Token()
495		if err != nil {
496			return nil, err
497		}
498		d, ok := t.(json.Delim)
499		if !ok || d != '{' {
500			return nil, fmt.Errorf("%s", notObjectMsg)
501		}
502		labels := map[string]string{}
503		for dec.More() {
504			labelKeyTok, err := dec.Token()
505			if err != nil {
506				return nil, err
507			}
508			labelKey := labelKeyTok.(string)
509			if labelKey == "" {
510				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
511			}
512			// 先判重再读值：与采样点/查询字段的判重一致，重复键不被值的类型掩盖。
513			if _, dup := labels[labelKey]; dup {
514				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
515			}
516			valTok, err := dec.Token()
517			if err != nil {
518				return nil, err
519			}
520			labelVal, ok := valTok.(string)
521			if !ok {
522				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
523			}
524			labels[labelKey] = labelVal
525		}
526		if _, err := dec.Token(); err != nil { // 消耗 '}'
527			return nil, err
528		}
529		return labels, nil
530	}
531	
532	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
533		t, err := dec.Token()
534		if err != nil {
535			return "", err
536		}
537		n, ok := t.(json.Number)
538		if !ok {
539			return "", fmt.Errorf(`field %q must be a JSON number`, field)
540		}
541		return n, nil
542	}
543	
544	func parseJSONInt(n json.Number) (int64, error) {
545		s := string(n)
546		if !jsonIntegerRE.MatchString(s) {
547			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
548		}
549		v, err := strconv.ParseInt(s, 10, 64)
550		if err != nil {
551			return 0, fmt.Errorf("must be within int64 range")
552		}
553		return v, nil
554	}
555	
556	func parseFiniteFloat(n json.Number) (float64, error) {
557		s := string(n)
558		if !jsonNumberRE.MatchString(s) {
559			return 0, fmt.Errorf("must be a JSON number")
560		}
561		v, err := strconv.ParseFloat(s, 64)
562		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
563			return 0, fmt.Errorf("must be a finite number representable as float64")
564		}
565		return v, nil
566	}
