568	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
569	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
570		type pending struct {
571			id  seriesID
572			ref SeriesRef
573			ts  int64
574			val float64
575		}
576	
577		added := 0
578		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
579		seen := make(map[seriesID]map[int64]float64)
580		// 仅记录需要落盘的新增点；校验全部通过后才提交。
581		commits := make([]pending, 0, len(items))
582	
583		failAt := func(index int, msg string) *LineError {
584			return &LineError{Status: "error", Index: index, Error: msg}
585		}
586		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
587			return &LineError{
588				Status: "error",
589				Index:  index,
590				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
591					ref, ts, formatFloat(existing), formatFloat(submitted)),
592				Conflict: &Conflict{
593					// 标签必须复制：冲突结果是本次失败的独立记录，
594					// 调用方修改它不能改动已存序列的身份。
595					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
596					Timestamp: ts,
597					Existing:  existing,
598					Submitted: submitted,
599				},
600			}
601		}
602	
603		for i, item := range items {
604			pos := i + 1
605			p, err := parseSample(item)
606			if err != nil {
607				return nil, failAt(pos, err.Error())
608			}
609	
610			id := makeSeriesID(p.name, p.labels)
611			ref := SeriesRef{Name: p.name, Labels: p.labels}
612	
613			if byTS, ok := seen[id]; ok {
614				if old, ok := byTS[p.ts]; ok {
615					if old != p.value {
616						return nil, conflictAt(pos, ref, p.ts, old, p.value)
617					}
618					// 同批内重复出现且数值相同：重复，成功忽略。
619					continue
620				}
621			}
622			if sr, ok := s.series[id]; ok {
623				if old, ok := sr.points[p.ts]; ok {
624					if old != p.value {
625						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
626					}
627					// 与此前批次已写入的值相同：重复，成功忽略。
628					// seen 记录的是已存值 old 而不是本次提交的 p.value：
629					// 数值相等但表示不同（如已存 +0、本次提交 -0）时，
630					// 本批后续在同位置的冲突必须如实报告首次接受的已存值，
631					// 不能被这条被忽略的重复改写。
632					if seen[id] == nil {
633						seen[id] = map[int64]float64{}
634					}
635					seen[id][p.ts] = old
636					continue
637				}
638			}
639	
640			added++
641			if seen[id] == nil {
642				seen[id] = map[int64]float64{}
643			}
644			seen[id][p.ts] = p.value
645			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
646		}
647	
648		// 全部采样点合法且无冲突，原子提交本批新增点。
649		for _, c := range commits {
650			sr := s.series[c.id]
651			if sr == nil {
652				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
653				s.series[c.id] = sr
654			}
655			sr.points[c.ts] = c.val
656		}
657	
658		return s.snapshot(added, len(items)-added), nil
659	}
