666	type parsedQuery struct {
667		name   string
668		start  int64
669		end    int64
670		labels map[string]string
671	}
672	
673	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
674	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
675		q, err := parseQuery(raw)
676		if err != nil {
677			return nil, &LineError{Status: "error", Error: err.Error()}
678		}
679		if q.start > q.end {
680			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
681				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
682		}
683		return s.runQuery(q), nil
684	}
685	
686	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
687	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
688	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
689		var q parsedQuery
690		err := parseStrictObject(raw,
691			"each query must be a JSON object",
692			"unexpected content after the query object",
693			[]string{"op", "name", "start", "end"},
694			map[string]fieldReader{
695				"op": func(dec *json.Decoder) error {
696					t, err := dec.Token()
697					if err != nil {
698						return err
699					}
700					op, ok := t.(string)
701					if !ok {
702						return fmt.Errorf(`field "op" must be a string`)
703					}
704					if op != "query" {
705						return fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
706					}
707					return nil
708				},
709				"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
710				"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
711				"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
712				"labels": func(dec *json.Decoder) error {
713					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
714				},
715			})
716		return q, err
717	}
718	
719	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
720	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
721	func labelsMatch(want, stored map[string]string) bool {
722		for k, v := range want {
723			got, ok := stored[k]
724			if !ok || got != v {
725				return false
726			}
727		}
728		return true
729	}
730	
731	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
732	// 序列次序与写入快照共用 organizeSeries 的整理结果：过滤掉其他序列后，
733	// 保留的序列仍是同一排序中的一个子序列，不另换排序；无区间内点的序列不列出。
734	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
735		inRange := func(ts int64) bool { return ts >= q.start && ts <= q.end }
736		out := make([]QuerySeries, 0)
737		for _, os := range s.organizeSeries() {
738			if os.ref.Name != q.name || !labelsMatch(q.labels, os.ref.Labels) {
739				continue
740			}
741			points := sortedSeriesPoints(os.sr, inRange)
742			if len(points) == 0 {
743				continue
744			}
745			values := make([]float64, len(points))
746			for i, p := range points {
747				values[i] = p.Value
748			}
749			out = append(out, QuerySeries{
750				Name:    os.ref.Name,
751				Labels:  os.ref.Labels,
752				Count:   len(values),
753				Average: finiteMean(values),
754			})
755		}
756		return &QueryResult{Status: "ok", Op: "query", Series: out}
757	}
758	
759	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
760	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
761	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
762	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
763	// 只有一个点时结果就是该点的值。
764	func finiteMean(values []float64) float64 {
765		sum := new(big.Rat)
766		r := new(big.Rat)
767		for _, v := range values {
768			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
769			sum.Add(sum, r.SetFloat64(v))
770		}
771		sum.Quo(sum, r.SetInt64(int64(len(values))))
772		return ratToFloat64NearestEven(sum)
773	}
774	
775	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
776	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
777	func ratToFloat64NearestEven(x *big.Rat) float64 {
778		if x.Sign() == 0 {
779			return 0
780		}
781		num := new(big.Int).Set(x.Num())
782		den := x.Denom()
783		neg := num.Sign() < 0
784		if neg {
785			num.Neg(num)
786		}
787	
788		// e 满足 2^e <= num/den < 2^(e+1)。
789		e := floorLog2Rat(num, den)
790		var m *big.Int
791		scale := 0
792		if e >= -1022 {
793			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
794			scale = e - 52
795			m = roundScaledRatio(num, den, scale)
796			if m.BitLen() == 54 {
797				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
798				m.Rsh(m, 1)
799				scale++
800			}
801		} else {
802			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
803			scale = -1074
804			m = roundScaledRatio(num, den, scale)
805		}
806		// m < 2^53，可以精确放入 int64 与 float64。
807		f := math.Ldexp(float64(m.Int64()), scale)
808		if neg {
809			return -f
810		}
811		return f
812	}
813	
814	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
815	func floorLog2Rat(num, den *big.Int) int {
816		k := num.BitLen() - den.BitLen()
817		var t big.Int
818		if k >= 0 {
819			t.Lsh(den, uint(k))
820			if num.Cmp(&t) >= 0 {
821				return k
822			}
823			return k - 1
824		}
825		t.Lsh(num, uint(-k))
826		if t.Cmp(den) >= 0 {
827			return k
828		}
829		return k - 1
830	}
831	
832	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
833	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
834		n := new(big.Int).Set(num)
835		d := new(big.Int).Set(den)
836		if scale >= 0 {
837			d.Lsh(d, uint(scale))
838		} else {
839			n.Lsh(n, uint(-scale))
840		}
841		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
842		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
843		case 1:
844			q.Add(q, big.NewInt(1))
845		case 0:
846			if q.Bit(0) == 1 {
847				q.Add(q, big.NewInt(1))
848			}
849		}
850		return q
851	}
852	
853	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
854	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
855	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
856	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
857	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
858	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
859	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
860	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
861	func (r SeriesRef) String() string {
862		var b strings.Builder
863		b.WriteString(identityText(r.Name))
864		b.WriteByte('{')
865		for i, p := range sortedPairs(r.Labels) {
866			if i > 0 {
867				b.WriteByte(',')
868			}
869			b.WriteString(identityText(p.Key))
870			b.WriteByte('=')
871			b.WriteString(identityText(p.Value))
872		}
873		b.WriteByte('}')
874		return b.String()
875	}
876	
877	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
878	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
879	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
880	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
881	// 因此渲染结果不会把内容字符误读为标签边界。
882	func identityText(s string) string {
883		if s == "" || s != strings.TrimSpace(s) {
884			return strconv.Quote(s)
885		}
886		for _, r := range s {
887			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
888				return strconv.Quote(s)
889			}
890		}
891		return s
892	}
893	
894	// organizedSeries 是一次结果整理中的一条序列：携带已存序列指针、
895	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
896	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
897	// 整理好的键值对，供排序比较直接复用。
898	type organizedSeries struct {
899		sr    *storedSeries
900		ref   SeriesRef
901		pairs []labelPair
902	}
903	
904	// organizeSeries 是写入快照与区间查询共用的数据整理逻辑：
905	// 遍历全部已提交序列，复制各自的序列身份，并按唯一的顺序约定排列——
906	// 先按指标名字符串字典序，再按标签键升序后的键值对逐对比较
907	// （先比键再比值，前一对相同才比下一对；较短集合是完整前缀时排前，
908	// 无标签序列因此排在最前）。标签值按字符串比较（"10" 在 "2" 之前）。
909	// 每条序列的标签只在遍历时整理一次：排序后的键值对随条目保留，
910	// sort 的反复比较直接复用同一份结果，不会因一条序列参与多次比较
911	// 而反复整理同一套标签。整理结果不复制采样点；采样点的选取与升序
912	// 排列由 sortedSeriesPoints 完成。
913	func (s *MetricStore) organizeSeries() []organizedSeries {
914		out := make([]organizedSeries, 0, len(s.series))
915		for _, sr := range s.series {
916			// 标签必须复制：成功结果是当次操作的独立记录，
917			// 调用方修改结果标签不能改动已存序列的身份。
918			labels := cloneLabels(sr.ref.Labels)
919			out = append(out, organizedSeries{
920				sr:    sr,
921				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
922				pairs: sortedPairs(labels),
923			})
924		}
925		sort.Slice(out, func(i, j int) bool {
926			if out[i].ref.Name != out[j].ref.Name {
927				return out[i].ref.Name < out[j].ref.Name
928			}
929			return compareLabelPairs(out[i].pairs, out[j].pairs) < 0
930		})
931		return out
932	}
933	
934	// sortedSeriesPoints 按 timestamp 升序返回一条已存序列中满足 keep 的采样点，
935	// 数值与时间戳一一对应。keep 为 nil 时返回全部点（写入快照）；
936	// 区间查询传入闭区间判定，查询只选取区间内的点。
937	// 返回的是新建切片与新建 Point，调用方对采样点的修改不影响存储，
938	// 也不影响此前或此后取得的其他成功结果。
939	func sortedSeriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
940		tsList := make([]int64, 0, len(sr.points))
941		for ts := range sr.points {
942			if keep == nil || keep(ts) {
943				tsList = append(tsList, ts)
944			}
945		}
946		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
947		points := make([]Point, len(tsList))
948		for i, ts := range tsList {
949			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
950		}
951		return points
952	}
953	
954	// snapshot 生成按规范排序的全部序列视图：序列次序与点排列均来自
955	// organizeSeries/sortedSeriesPoints 这套与查询共用的整理逻辑。
956	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
957		organized := s.organizeSeries()
958		views := make([]SeriesView, 0, len(organized))
959		for _, os := range organized {
960			views = append(views, SeriesView{
961				Name:   os.ref.Name,
962				Labels: os.ref.Labels,
963				Points: sortedSeriesPoints(os.sr, nil),
964			})
965		}
966		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
967	}
