126	// TestSnapshotOrderIndependentOfSubmissionOrder 是写入侧核心回归：同一组数据
127	// 无论正序、反序还是乱序提交（乱序还拆成三个批次），写入成功后全量快照中的
128	// 序列排列必须完全一致，且正是按“指标名原始字符串字典序 + 标签逐对字符串比较”
129	// 得到的规范顺序，与标签书写顺序、map 遍历或批次划分都无关。
130	func TestSnapshotOrderIndependentOfSubmissionOrder(t *testing.T) {
131		specs := orderingSpecs()
132		want := wantSigs(specs)
133	
134		backward := make([]identitySpec, len(specs))
135		for i, sp := range specs {
136			backward[len(specs)-1-i] = sp
137		}
138		shuffled := permutedSpecs(specs, shuffledOrderingPerm)
139	
140		// 三个存储以不同顺序/批次提交相同数据。
141		forward := NewMetricStore()
142		mustOK(t, forward, orderingBatch(specs))
143	
144		reversed := NewMetricStore()
145		mustOK(t, reversed, orderingBatch(backward))
146	
147		chunked := NewMetricStore()
148		for _, cut := range [][2]int{{0, 7}, {7, 14}, {14, 21}} {
149			mustOK(t, chunked, orderingBatch(shuffled[cut[0]:cut[1]]))
150		}
151	
152		// 每个存储再用一个空批取全量快照：快照来自当下存储，与本批 added 无关，
153		// 三份身份排列必须逐一相同。
154		snaps := []*BatchResult{
155			mustOK(t, forward, `[]`),
156			mustOK(t, reversed, `[]`),
157			mustOK(t, chunked, `[]`),
158		}
159		for i, snap := range snaps {
160			if got := snapshotIdentitySigs(snap); !reflect.DeepEqual(got, want) {
161				t.Fatalf("store %d snapshot order = %v\nwant %v", i, got, want)
162			}
163			if len(snap.Series) != len(specs) {
164				t.Fatalf("store %d series count = %d, want %d", i, len(snap.Series), len(specs))
165			}
166		}
167	
168		// 关键相邻关系单独点名，防止错误实现悄悄溜过：
169		got := snapshotIdentitySigs(snaps[0])
170		cpuCount := 0
171		for _, s := range snaps[0].Series {
172			if s.Name == "cpu" {
173				cpuCount++
174			}
175		}
176		if cpuCount != 19 {
177			t.Fatalf("cpu series = %d, want 19", cpuCount)
178		}
179		// 无标签 cpu 是同名序列中的第一条；指标名 cpu,total 与 指标 在全部 cpu 之后，
180		// 且 "cpu" < "cpu,total" < "指标"（按原始字符串，逗号与中文都不特殊处理）。
181		if snaps[0].Series[0].Name != "cpu" || len(snaps[0].Series[0].Labels) != 0 {
182			t.Fatalf("first series = %+v, want unlabeled cpu", snaps[0].Series[0])
183		}
184		if got[19] != identitySig("cpu,total", map[string]string{}) ||
185			got[20] != identitySig("指标", map[string]string{"k": "v"}) {
186			t.Fatalf("metric-name ordering = %q, %q", got[19], got[20])
187		}
188	
189		// 每条序列快照里的点仍是各自的点：身份与采样值按时间戳升序对应，
190		// 不允许为了排列序列而串换不同序列的数据。
191		for i, sp := range specs {
192			idx := findViewIndex(t, snaps[0], sp.name, sp.labels)
193			pts := snaps[0].Series[idx].Points
194			if len(pts) != 1 || pts[0] != (Point{Timestamp: sp.ts, Value: sp.value}) {
195				t.Fatalf("series %s points = %+v, want (%d,%v)", got[i], pts, sp.ts, sp.value)
196			}
197		}
