468			t.Fatalf("escaped resubmit = added %d duplicates %d, want 0/2", dup.Added, dup.Duplicates)
469		}
470		if got := snapshotIdentitySigs(dup); !reflect.DeepEqual(got, wantSigs(specs)) {
471			t.Fatalf("order changed after escaped duplicates: %v", got)
472		}
473	
474		// 以转义写法对引号值序列提交不同数值：整批冲突拒绝，结构化身份是解析后的
475		// 真实标签 {k:"}（不是渲染文本 k="\""），原因文本中的引号只为可辨识，
476		// 不改变排序依据的身份。
477		lerr := mustFail(t, encoded,
478			"["+escapedSample(identitySpec{name: "cpu", labels: map[string]string{"k": `"`}, ts: 113, value: 999}, escape)+"]")
479		if lerr.Conflict == nil || lerr.Conflict.Existing != 14 || lerr.Conflict.Submitted != 999 {
480			t.Fatalf("escaped conflict detail = %+v", lerr.Conflict)
481		}
482		if !reflect.DeepEqual(lerr.Conflict.Series.Labels, map[string]string{"k": `"`}) {
483			t.Fatalf("escaped conflict labels = %v, want parsed {k:\"}", lerr.Conflict.Series.Labels)
484		}
485		if !strings.Contains(lerr.Error, `series cpu{k="\""} at timestamp 113`) {
486			t.Fatalf("escaped conflict message = %q", lerr.Error)
487		}
488		// 冲突拒绝不改变事实与排列。
489		if got := mustQuery(t, encoded, queryLabels("cpu", 113, 113, map[string]string{"k": `"`})); got.Series[0].Average != 14 {
490			t.Fatalf("value changed after rejected conflict batch: %+v", got.Series)
491		}
492	}
